mapper.update:
UPDATE CAM_RU_PARTITION_LEASE
SET leader_id = #{leaderId}, zone = #{zone}, term = term + 1, renewal_counter = 0,
    released = FALSE
WHERE partition_id = #{partitionId}
  AND term = #{observedTerm}
  AND renewal_counter = #{observedCounter}

UPDATE CAM_RU_PARTITION_LEASE
SET renewal_counter = renewal_counter + 1, released = TRUE
WHERE partition_id = #{partitionId}
  AND leader_id = #{leaderId}
  AND term = #{term}
  AND released = FALSE

mapper.select:
SELECT partition_id, leader_id, zone, term, renewal_counter, released
FROM CAM_RU_PARTITION_LEASE
WHERE partition_id = #{partitionId}
